# Browser end-to-end test: streamer goes live with a fake camera, viewer watches, pins, streamer answers.
import os, subprocess, time, tempfile, sys
from playwright.sync_api import sync_playwright
PORT = 3997; BASE = f'http://localhost:{PORT}'
env = {**os.environ, 'PORT': str(PORT), 'DB_PATH': tempfile.mktemp(suffix='.db'), 'ADMIN_USERNAMES': 'siteroot'}
srv = subprocess.Popen(['node', 'server.js'], env=env, cwd=os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
time.sleep(1.5)
ok = True
def check(n, c):
    global ok; print(('PASS ' if c else 'FAIL ') + n); ok = ok and bool(c)
def signup(page, name):
    page.goto(BASE + '/#/signup'); page.fill('input[name=username]', name)
    page.fill('input[name=password]', 'password123'); page.fill('input[name=dob]', '2001-05-05'); page.check('input[name=terms]')
    page.click('button[type=submit]'); page.wait_for_selector('text=Go live')
try:
    with sync_playwright() as p:
        b = p.chromium.launch(args=['--use-fake-device-for-media-stream', '--use-fake-ui-for-media-stream'])
        s = b.new_context(permissions=['camera', 'microphone'], bypass_csp=True).new_page()
        v = b.new_context(bypass_csp=True).new_page()
        errs = []; s.on('pageerror', lambda e: errs.append(str(e))); v.on('pageerror', lambda e: errs.append(str(e)))
        signup(s, 'dawnstream'); signup(v, 'earlyfan')
        s.goto(BASE + '/#/golive'); s.click('text=Use camera'); s.wait_for_function('!document.querySelector(".btn.primary[disabled]")', polling=300)
        s.fill('input[aria-label="Stream title"]', 'Study with me'); s.click('text=Start stream')
        s.wait_for_selector('text=End stream'); check('streamer is live', True)
        v.goto(BASE + '/'); v.wait_for_selector('a.card'); check('stream appears on home', True)
        v.click('a.card')
        v.wait_for_function('(()=>{const e=document.querySelector("video");return e&&e.videoWidth>0})()', timeout=15000, polling=300)
        check('viewer receives live video over WebRTC', True)
        v.wait_for_selector('text=Early Bird #1'); check('first viewer is Early Bird #1', True)
        v.click('button.pinbtn'); v.fill('.composer input', 'What are you studying?'); v.press('.composer input', 'Enter')
        s.wait_for_selector('.pins .pin >> text=What are you studying?'); check('pin shows on streamer dashboard', True)
        s.click('.pins >> text=Answered'); v.wait_for_selector('.shout'); check('Answered shout-out reaches viewer', True)
        time.sleep(0.3); check('pin removed after answer', s.locator('.pins .pin').count() == 0)
        # ---- Phase 1 UI ----
        v.click('.react >> nth=2'); s.wait_for_selector('.fl'); check('reaction floats on the streamer screen', True)
        s.click('.modbar >> text=Poll'); s.fill('.pollform input[aria-label="Poll question"]', 'Best snack?')
        s.fill('.pollform input[aria-label="Option 1"]', 'Chips'); s.fill('.pollform input[aria-label="Option 2"]', 'Fruit')
        s.click('.pollform >> text=Start poll'); v.wait_for_selector('.poll .opt'); check('poll appears for viewer', True)
        v.click('.poll .opt >> nth=0'); v.wait_for_selector('.poll .opt.mine'); check('viewer can vote in the poll', True)
        v.click('button:has-text("Theatre")'); check('theatre mode toggles', v.locator('#channel.theatre').count() == 1)
        v.click('button:has-text("Fullscreen")'); check('player controls present', v.locator('.ctrls button').count() >= 3)
        s.goto(BASE + '/#/u/dawnstream'); s.click('text=Edit profile')
        s.fill('input[maxlength="30"]', 'Nova Dawn'); s.fill('input[aria-label="Avatar emoji"]', '🦊')
        s.fill('input[aria-label="Link 1"]', 'https://youtube.com/@dawn'); s.click('button:has-text("Save")')
        s.wait_for_selector('h1:has-text("Nova Dawn")'); check('profile edit saves and shows', True)
        check('profile link is shown', s.locator('a:has-text("YouTube")').count() == 1)
        s.goto(BASE + '/#/dashboard'); s.wait_for_selector('text=Creator dashboard'); s.wait_for_selector('.stat')
        check('creator dashboard loads stats', s.locator('.stat').count() >= 10)
        check('page title is NovaStream', 'NovaStream' in s.title())
        # ---- Phase 2 UI ----
        s.goto(BASE + '/#/feed'); s.wait_for_selector('h1:has-text("Community feed")')
        s.fill('textarea[aria-label="New post"]', 'Hello NovaStream! Welcome @earlyfan'); s.click('.composer2 button[type=submit]')
        s.wait_for_selector('.post'); check('feed: post appears after publishing', s.locator('.post').count() == 1)
        s.click('.post .fbp-like'); s.wait_for_selector('.fbp-like.on'); check('feed: reaction toggles on', True)
        time.sleep(3.3)  # anti-spam cooldown between posts and comments
        s.click('.post .fbp-comment'); s.fill('.fbp-cbox input[aria-label="Comment"]', 'First comment!'); s.press('.fbp-cbox input[aria-label="Comment"]', 'Enter')
        s.wait_for_selector('.fbp-cmt'); check('feed: comment appears', s.locator('.fbp-cmt').count() == 1)
        v.wait_for_selector('#bellcount:not([hidden])', timeout=8000); check('notifications: bell shows a live unread count', True)
        v.goto(BASE + '/#/notifications'); v.wait_for_selector('.nitem.unread >> text=mentioned you')
        check('notifications: mention is listed', v.locator('.nitem:has-text("mentioned you")').count() >= 1)
        s.goto(BASE + '/#/circles/new'); s.fill('input[required]', 'Study Hall'); s.fill('textarea', 'Quiet focus time'); s.click('button:has-text("Create Circle")')
        s.wait_for_selector('h1:has-text("Study Hall")'); check('circles: owner can create a Circle', True)
        v.goto(BASE + '/#/circles'); v.wait_for_selector('.ccard'); v.click('.ccard button:has-text("Join")')
        v.wait_for_selector('.ccard button:has-text("Joined")'); check('circles: viewer can join from the list', True)
        v.goto(BASE + '/#/search/Study'); v.wait_for_selector('.ccard'); check('search: finds the Circle', v.locator('.ccard').count() >= 1)
        s.goto(BASE + '/#/u/dawnstream'); s.wait_for_selector('text=Community appreciation'); check('profile: appreciation card shows', True)
        # ---- Safety, accounts and admin UI ----
        fresh = b.new_context(bypass_csp=True).new_page()
        fresh.goto(BASE + '/#/signup'); fresh.fill('input[name=username]', 'noagree'); fresh.fill('input[name=password]', 'password123'); fresh.fill('input[name=dob]', '2001-05-05')
        fresh.click('button[type=submit]'); time.sleep(0.6)
        check('sign-up cannot be completed without agreeing to the terms', fresh.evaluate("localStorage.getItem('novastream_token')") is None)
        check('sign-up explains the under-18 protections', fresh.locator('.teennote').count() == 1)
        v.goto(BASE + '/#/legal/terms'); v.wait_for_selector('h1:has-text("Terms of Service")'); check('legal: terms page shows', True)
        v.goto(BASE + '/#/settings'); v.wait_for_selector('h1:has-text("Account settings")'); check('account settings page shows', v.locator('button:has-text("Download my data")').count() == 1)
        adm = b.new_context(bypass_csp=True).new_page(); signup(adm, 'siteroot')
        v.goto(BASE + '/#/u/dawnstream'); v.click('button:has-text("Report")'); v.wait_for_selector('.modalbox')
        v.select_option('.modalbox select', 'harassment'); v.fill('.modalbox textarea', 'rude to me'); v.click('.modalbox button:has-text("Send report")')
        v.wait_for_selector('.toast:has-text("review your report")'); check('report dialog sends a report', True)
        adm.goto(BASE + '/#/admin/reports'); adm.wait_for_selector('.rcard'); check('admin sees the report in the queue', adm.locator('.rcard:has-text("@earlyfan")').count() == 1)
        adm.select_option('.rcard select[aria-label="Action"]', 'warn'); adm.fill('.rcard input[aria-label="Reason"]', 'please be kind')
        adm.click('.rcard button:has-text("Resolve")'); adm.wait_for_selector('text=No open reports'); check('admin can resolve a report', True)
        adm.goto(BASE + '/#/admin/overview'); adm.wait_for_selector('.stats'); check('admin overview shows live numbers', adm.locator('.stat').count() >= 10)
        adm.goto(BASE + '/#/admin/users'); adm.wait_for_selector('.atr:has-text("dawnstream")'); check('admin can find accounts', True)
        adm.click('.atr:has-text("dawnstream") button:has-text("Manage")'); adm.wait_for_selector('.manage'); check('admin can open an account', adm.locator('.manage button:has-text("Suspend")').count() == 1)
        adm.goto(BASE + '/#/admin/settings'); adm.wait_for_selector('input[aria-label="Announcement"]')
        adm.fill('input[aria-label="Announcement"]', 'Hello everyone'); adm.click('button:has-text("Save settings")'); adm.wait_for_selector('.toast:has-text("Settings saved")')
        v.reload(); v.wait_for_selector('#banner:not([hidden])'); check('an admin announcement reaches everyone', 'Hello everyone' in v.inner_text('#banner'))
        adm.goto(BASE + '/#/admin/backups'); adm.click('button:has-text("Back up now")'); adm.wait_for_selector('.toast:has-text("Backup created")'); check('admin can create a backup from the page', True)
        s.goto(BASE + '/#/notifications'); s.wait_for_selector('.nitem:has-text("Warning from NovaStream staff")'); check('the person reported receives the admin warning', True)
        v.goto(BASE + '/#/notifications'); v.wait_for_selector('.nitem:has-text("took action")'); check('the person who reported is told it was handled', True)
        v.goto(BASE + '/#/admin'); check('normal users cannot open the admin area', v.locator('text=Admins only').count() >= 1 or v.locator('h1:has-text("Admins only")').count() == 1)
        check('no JS errors', not errs)
        if errs: print(errs)
        b.close()
finally:
    srv.terminate()
print('ALL PASSED' if ok else 'SOME FAILED'); sys.exit(0 if ok else 1)
